const convertToGeoJSON = (polygons) => {
  return polygons.map(polygon => {
    const coordinates = polygon.coordinate[0].points.map(point => [point.lng, point.lat]);
    return {
      type: "Feature",
      geometry: {
        type: "Polygon",
        coordinates: [coordinates]
      },
      properties: {
        name: polygon.name.split('-')[0] || polygon.name,
        regionName: polygon.name.split('-')[1] || polygon.name
      },
      polygonType: "circle",
      "__v": 0
    };
  });
};
